mapper.update:
UPDATE `order`

    `count` = #{count},
    status = #{status},
    travelDate = #{travelDate},
    totalPrice = #{totalPrice}

WHERE id = #{id}

mapper.select:
SELECT o.id, o.orderNo, o.userId, o.ticketId, o.orderType, o.hotelId, o.`count`, o.status, o.createTime, o.travelDate, o.totalPrice, o.person_name AS personName, o.phone AS phone, COALESCE(t.name, h.name, '') AS ticketName, h.name AS hotelName FROM `order` o LEFT JOIN ticket t ON o.ticketId = t.id LEFT JOIN hotel h ON o.hotelId = h.id
AND o.orderNo LIKE CONCAT('%',#{order.orderNo},'%')
AND o.userId = #{order.userId}
AND o.orderType = #{order.orderType}
AND o.status = #{order.status}
AND o.createTime >= #{order.startDate}
AND o.createTime < DATE_ADD(#{order.endDate}, INTERVAL 1 DAY)
ORDER BY o.id DESC LIMIT #{start}, #{pageSize}

SELECT COUNT(*)
FROM `order` o
LEFT JOIN ticket t ON o.ticketId = t.id


        AND o.orderNo LIKE CONCAT('%',#{order.orderNo},'%')


        AND o.userId = #{order.userId}


        AND o.orderType = #{order.orderType}


        AND o.status = #{order.status}



        AND o.createTime >= #{order.startDate}


        AND o.createTime < DATE_ADD(#{order.endDate}, INTERVAL 1 DAY)
